\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\title{Soil Moisture Telemetry for\\Terrace Farms in the Highlands}
\author{L.~Okafor and M.~Reyes}
\date{May 2026}
\begin{document}
\maketitle
\begin{abstract}
We deploy a low-cost soil-moisture telemetry network across eleven
terrace farms and report one growing season of measurements.
The network combines capacitive probes with a store-and-forward radio
link, and the collected data support irrigation scheduling that cut
water use by roughly one fifth without measurable yield penalties.
\end{abstract}
\section{Introduction}
Terrace farms in the highlands face short growing seasons and
unreliable water allocation, and most scheduling decisions still rely
on habit rather than measurement.
Figure \ref{fig:arch} sketches the telemetry chain we deployed, and
Figure \ref{fig:map} shows where the eleven farms sit along the
valley.
The season-long traces, summarized in Figure \ref{fig:dashboard},
gave farmers a shared picture of moisture dynamics for the first
time.
\section{System Overview}
Each node samples soil moisture every fifteen minutes and forwards
readings to a solar-powered gateway at the cooperative office.
Figure \ref{fig:arch} shows the end-to-end path from probe to
gateway.
\begin{figure}[h]
\centering
\fbox{\parbox[c][4cm][c]{0.6\linewidth}{\centering Architecture diagram placeholder}}
\caption{End-to-end telemetry architecture from probe to gateway.}
\label{fig:arch}
\end{figure}
The store-and-forward link tolerates the multi-day connectivity gaps
that are common after storms.
\section{Sensor Hardware}
The probe pairs a capacitive sensor with a low-power radio and a
solar trickle charger, as shown in Figure \ref{fig:sensor}.
\begin{figure}[h]
\centering
\fbox{\parbox[c][4cm][c]{0.6\linewidth}{\centering Probe assembly placeholder}}
\caption{Probe assembly with capacitive sensor and solar trickle charger.}
\label{fig:sensor}
\end{figure}
Field calibration against gravimetric samples kept the absolute error
within two percentage points across the season.
\section{Field Deployment}
We installed two nodes per farm, one near the upper terrace and one
near the irrigation outlet, as mapped in Figure \ref{fig:map}.
\begin{figure}[h]
\centering
\fbox{\parbox[c][6cm][c]{0.85\linewidth}{\centering Deployment map placeholder}}
\caption{Deployment map of the eleven terrace farms with node positions.}
\label{fig:map}
\end{figure}
The season dashboard in Figure \ref{fig:dashboard} aggregates the
daily traces for all terraces.
\begin{figure}[h]
\centering
\fbox{\parbox[c][6cm][c]{0.85\linewidth}{\centering Season dashboard placeholder}}
\caption{Season dashboard with daily moisture traces per terrace.}
\label{fig:dashboard}
\end{figure}
Node uptime averaged 94 percent, with outages concentrated in the
week after the heaviest storm.
\section{Results and Conclusion}
Irrigation events fell by roughly one fifth once scheduling followed
the traces instead of habit, and yield estimates from the cooperative
showed no measurable penalty.
A second season is planned with denser nodes on the three farms that
showed the largest within-terrace variability.
\end{document}

